const $=s=>document.querySelector(s);
let data;
const fmt=s=>`(${s[0]}, ${s[1]})`;
const image=(src,title)=>`<button class="image-button" data-image="${src}" data-title="${title}" aria-label="Enlarge ${title}"><img loading="lazy" src="${src}" alt="${title}"></button>`;
function card(e,mode){const r=e[mode];const src=r?.image;if(!src)return `<article class="photo-card"><div class="empty">Result image unavailable.</div><h3>${e.title}</h3></article>`;const label=mode==='final'?'final notebook output':mode==='single'?'single-scale pixel L2':'pyramid pixel L2';const meta=mode==='final'?'Final output':`G ${fmt(r.green)} &nbsp; R ${fmt(r.red)} · (dy, dx)`;return `<article class="photo-card">${image(src,e.title+' — '+label)}<h3>${e.title}</h3><p class="meta">${meta}</p>${e.note&&mode==='pyramid'?`<p class="note flag">${e.note}</p>`:''}</article>`}
function renderGallery(){$('#main-results').innerHTML=data.results.map(e=>card(e,$('#gallery-method').value)).join('')}
function comparison(title,description,before,after,left,right,fine=''){return `<article class="experiment"><div class="experiment-heading"><h3>${title}</h3><p>${description}</p></div><div class="comparison"><figure>${image(before,left)}<figcaption>${left}</figcaption></figure><figure>${image(after,right)}<figcaption>${right}</figcaption></figure></div>${fine?`<p class="fine">${fine}</p>`:''}</article>`}
async function init(){try{data=JSON.parse($('#results-data').textContent);$('#single-results').innerHTML=data.results.filter(e=>e.lowres).map(e=>card(e,'single')).join('');renderGallery();$('#offset-table').innerHTML=data.results.filter(e=>e.pyramid).map(e=>`<tr><td>${e.title}</td><td>${fmt(e.pyramid.green)}</td><td>${fmt(e.pyramid.red)}</td><td>${e.originalShape[0]} × ${e.originalShape[1]}</td></tr>`).join('');let experiments='';const emir=data.results.find(e=>e.id==='emir');const self=data.results.find(e=>e.id==='self_portrait');if(self?.crop){experiments+=comparison('Question 3 / Automatic Cropping','First remove pixels that wrapped during translation. Then detect near-black (< 0.14) or near-white (> 0.95) pixels separately in each channel. Search the outer 10%; a five-row or five-column window qualifies at 90%. Use the largest detected crop on each side for all channels.',self.gradient.image,self.final.image,'Self portrait · valid overlap only','Self portrait · detected border crop','The 10% band limits the search; it is not a fixed crop. Very bright sky and dark scene content can cause over-cropping.');experiments+=comparison('Question 4 / Automatic Contrasting','The notebook uses the 1st and 99th intensity percentiles as robust black and white points, then clips the result to [0, 1]. This reduces the influence of a few extreme border or scratch pixels.',self.balance,self.contrast,'Before percentile contrast','After percentile contrast','This comparison holds the white-balanced input fixed so the contrast change can be seen by itself.');experiments+=comparison('Question 5 / Automatic White Balance','Gray-world white balance rescales each channel so its mean equals the average of the three channel means. This counters a global color cast, but depends on the scene having a roughly neutral average.',self.crop,self.balance,'Before white balance','After gray-world white balance');experiments+=comparison('Question 6 / Better Color Mapping','This comparison uses the Emir final output before adjustment, then the saved color-adjusted Emir result.',emir.final.image,'assets/emir-color-adjustment.jpg','Emir · final output','Emir · after color adjustment','Both images use the same alignment; this stage changes only color processing.');}if(emir?.gradient)experiments+=comparison('Question 7 / Better Features: Gradient Alignment','For each channel, the horizontal and vertical derivatives Gx and Gy are combined into gradient magnitude √(Gx² + Gy²). The pyramid search then minimizes L2 distance between gradient-magnitude images instead of raw intensities.',emir.pyramid.image,emir.gradient.image,'Emir · raw-pixel L2','Emir · gradient-magnitude L2',`Gradient offsets: G ${fmt(emir.gradient.green)}, R ${fmt(emir.gradient.red)}. Separate Gx and Gy pictures are not required because the alignment score uses their combined magnitude.`);$('#experiment-results').innerHTML=experiments||'<p class="empty">Controlled notebook comparisons are being prepared.</p>';$('#observations').innerHTML=data.observations||'';}catch(e){$('#main-results').textContent='The result records could not be loaded. Please serve this folder with a local web server.';console.error(e)}}
$('#gallery-method').addEventListener('change',renderGallery);
$('#results .section-heading > p').innerHTML=`For the large TIFF scans, I use a coarse-to-fine image pyramid. I repeatedly downsample both channels by a factor of two until the image is about 375 pixels wide, search ±15 pixels at the coarsest level, then return toward full resolution. At every larger level, I double the previous shift and search within ±3 pixels for a correction.<br><br><strong>Final output</strong> shows the images after the complete pipeline: pyramid alignment with gradient-magnitude features, valid-overlap and detected-border cropping, gray-world white balance, percentile contrast, and the final color adjustment. Choose <strong>Raw-pixel L2</strong> to inspect the required multi-scale alignment baseline by itself.`;
document.addEventListener('click',e=>{const b=e.target.closest('[data-image]');if(!b)return;$('#lightbox-image').src=b.dataset.image;$('#lightbox-image').alt=b.dataset.title;$('#lightbox-caption').textContent=b.dataset.title;$('#lightbox').showModal()});$('#close-lightbox').onclick=()=>$('#lightbox').close();$('#lightbox').addEventListener('click',e=>{if(e.target===$('#lightbox'))$('#lightbox').close()});init();
